  "inlineSchema": "// Prisma schema for Subscription Microservice\n// Multi-tenant model with RBAC, plans, plan_prices, subscriptions, and payment tracking.\n// Plan model follows Approach A: one Product (per tier) holds many Prices (one per cadence).\n// Legacy fields on Plan (amount/currency/interval/gatewayPlanId) are kept for backwards\n// compatibility with rows created under the Approach B prototype.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// PLANS (the marketing tier / product concept)\n// ============================================\nmodel Plan {\n  id          String     @id @default(uuid())\n  tenantId    String\n  name        String\n  slug        String\n  description String?\n  productId   String? // Stripe prod_... shared across this plan's prices\n  features    Json? // Per-tier entitlement blob (doc §12.6)\n  status      PlanStatus @default(DRAFT)\n  isActive    Boolean    @default(true)\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  // --- legacy fields (Approach B prototype) — kept for back-compat only ---\n  amount          Decimal?         @db.Decimal(10, 2)\n  currency        String?          @default(\"USD\")\n  interval        BillingInterval?\n  intervalCount   Int?\n  trialDays       Int?\n  gatewayPlanId   String? // Legacy: was a Stripe price_... under Approach B\n  gatewaySyncedAt DateTime?\n\n  prices        PlanPrice[]\n  subscriptions Subscription[]\n\n  @@unique([tenantId, slug])\n  @@index([tenantId])\n  @@index([status])\n  @@map(\"plans\")\n}\n\nenum PlanStatus {\n  DRAFT\n  ACTIVE\n  ARCHIVED\n}\n\nenum BillingInterval {\n  DAY\n  WEEK\n  MONTH\n  YEAR\n}\n\n// ============================================\n// PLAN PRICES (one Stripe price_... per cadence/feature)\n// Multiple prices live under one Plan (Approach A).\n// ============================================\nmodel PlanPrice {\n  id              String           @id @default(uuid())\n  planId          String\n  plan            Plan             @relation(fields: [planId], references: [id], onDelete: Cascade)\n  gatewayPriceId  String? // Stripe price_... once published\n  amount          Int // smallest currency unit (cents)\n  currency        String           @default(\"USD\")\n  interval        BillingInterval?\n  intervalCount   Int              @default(1)\n  type            PriceType        @default(RECURRING)\n  usageType       UsageType        @default(LICENSED)\n  trialDays       Int              @default(0)\n  nickname        String? // \"monthly\", \"yearly\", \"setup\", \"per_call\" — display only\n  status          PriceStatus      @default(DRAFT)\n  gatewaySyncedAt DateTime?\n  isActive        Boolean          @default(true)\n\n  // --- USD snapshot (immutable, captured at create/publish) ---\n  // Display uses `amount` + `currency` (the user's original price, e.g. ₹299).\n  // Reporting uses `amountUsdCents` (the USD cents equivalent at capture time).\n  // FX fields are write-once; never recomputed.\n  amountUsdCents Int? // USD amount in cents (smallest unit). NULL only for legacy rows.\n  fxRate         Decimal?  @db.Decimal(18, 8) // foreign-per-USD (e.g. 83.50 INR per 1 USD). 1.0 for USD.\n  fxAsOf         DateTime? // When the FX rate was captured\n  fxSource       String? // \"stripe\" | \"manual\" — origin of the rate\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([planId])\n  @@index([status])\n  @@map(\"plan_prices\")\n}\n\nenum PriceType {\n  RECURRING\n  ONE_TIME\n}\n\nenum UsageType {\n  LICENSED\n  METERED\n}\n\nenum PriceStatus {\n  DRAFT\n  ACTIVE\n  ARCHIVED\n}\n\n// ============================================\n// SUBSCRIPTIONS\n// ============================================\nmodel Subscription {\n  id                    String             @id @default(uuid())\n  tenantId              String\n  userId                String\n  planId                String\n  plan                  Plan               @relation(fields: [planId], references: [id])\n  planPriceId           String? // Primary recurring price (Approach A)\n  addons                String[]           @default([]) // Additional planPriceIds (one-time setup fees, etc.)\n  status                SubscriptionStatus @default(ACTIVE)\n  gatewayProvider       String // 'stripe', 'paypal', etc.\n  gatewaySubscriptionId String? // Provider-side ID\n  gatewayCustomerId     String?\n  currentPeriodStart    DateTime\n  currentPeriodEnd      DateTime\n  cancelAtPeriodEnd     Boolean            @default(false)\n  cancelledAt           DateTime?\n  createdAt             DateTime           @default(now())\n  updatedAt             DateTime           @updatedAt\n\n  invoices Invoice[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  TRIALING\n  PAST_DUE\n  CANCELLED\n  PAUSED\n  EXPIRED\n}\n\n// ============================================\n// INVOICES\n// ============================================\nmodel Invoice {\n  id               String        @id @default(uuid())\n  tenantId         String\n  subscriptionId   String?\n  subscription     Subscription? @relation(fields: [subscriptionId], references: [id])\n  amount           Decimal       @db.Decimal(10, 2)\n  currency         String        @default(\"USD\")\n  status           InvoiceStatus @default(PENDING)\n  gatewayInvoiceId String?\n  paidAt           DateTime?\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  @@index([tenantId])\n  @@index([subscriptionId])\n  @@index([status])\n  @@map(\"invoices\")\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n  VOID\n}\n",
